			const { Client } = await Promise.resolve().then(() => (init_client(), client_exports));
			const client = await Client.from({
				contractId,
				rpcUrl: this.serverURL.toString(),
				networkPassphrase: passphrase,
				server: this
			});
			const isContractMethod = client.spec.funcs().some((fn) => fn.name.toString() === method);
			const { sanitizeIdentifier } = await Promise.resolve().then(() => (init_utils(), utils_exports));
			const invoke = client[sanitizeIdentifier(method)];
			if (!isContractMethod || typeof invoke !== "function") throw new TypeError(`Contract ${contractId} has no method '${method}'`);
			const assembled = await invoke(args);
			return {
				result: assembled.result,
				isReadCall: assembled.isReadCall
			};
